args.new_text:
if phase == "dynamic":
    # Try to get runtime content from first active agent for per-agent fields
    active = list(getattr(engine, "active_agents", []))
    content = ""
    preview_note = ""
    if active:
        # Try with first active agent to get per-agent fields (persona, examples, instructions)
        first_agent = active[0]
        agent_dict = {}
        gc = getattr(engine, "groupchat", None)
        if gc and hasattr(gc, "agents"):
            agent_dict = gc.agents.get(first_agent, {})
        content = engine.prompt_builder._get_component_content(
            first_agent, agent_dict, key, active,
        )
        if content:
            preview_note = f"\n📌 以 {first_agent} 为例展示"
    # Fallback: try with empty agent (gets template-based content)
    if not content:
        content = engine.prompt_builder._get_component_content(
            "__preview__", {}, key, active,
        )
    # Final fallback: show global template if still empty
    if not content:
        content = PromptBuilder.get_component_template(key) or ""
    source = PromptBuilder.get_component_source(key)
    header = f"👁 预览动态组件 - {label} [{phase_label}]\n⚡ 来源: {source}{preview_note}"
    buttons = [[InlineKeyboardButton("↩ 返回", callback_data="pr:refresh")]]

args.old_text:
if key == "history":
    buttons.append([InlineKeyboardButton(f"📜 {label}", callback_data="pr:refresh")])
